prts.feedbackvariables:
matlist:[ans4,ans3,ans2,ans1];
matlist2:[ans1,ans2,ans3,ans4];
matrixInput: is(delete(true,map(matrixp,matlist)) = []);
isSquare(M):= is(length(M) = dm and length(M[1]) = dm);
validInput: if (matrixInput) then is(delete(true,map(isSquare,matlist))=[]) else false;
isEl: if (validInput) then is(delete(true,map(isElementary,matlist))=[]) else false;

multipliedAns: if isEl then lreduce(lambda([x,y],x.y),matlist,ident(dm)) else "Invalid Input err";

multipliedAns2: if isEl then lreduce(lambda([x,y],x.y),matlist2,ident(dm)) else "Invalid Input err";
